<?php
declare(strict_types=1);
$pageData = (array) ($billingContext['data']['page'] ?? []); $rows = (array) ($pageData['rows'] ?? []); $query = (array) ($billingContext['query'] ?? []);
?>
<div data-billing-services><div class="portal-card-head"><div><strong>Xidmet aktivliyi</strong><small>Abonent xidmetinin billing statusu, paketi ve bitme tarixi.</small></div></div><form class="billing-filter" method="get" action="billing-services.php" data-billing-filter><div class="portal-form-row"><label>Axtaris</label><input type="search" name="search" value="<?= e((string) ($query['search'] ?? '')); ?>" placeholder="Login, abonent, IP, paket"></div><div class="portal-form-row"><label>Status</label><select name="status"><option value="">Hamisi</option><?php foreach (['active' => 'Aktiv', 'expired' => 'Bitmis', 'suspended' => 'Dayandirilmis', 'disabled' => 'Passiv'] as $value => $label): ?><option value="<?= e($value); ?>"<?= ($query['status'] ?? '') === $value ? ' selected' : ''; ?>><?= e($label); ?></option><?php endforeach; ?></select></div><button class="portal-primary-btn" type="submit">Tetbiq et</button></form><div class="portal-table-wrap"><table class="portal-table"><thead><tr><th>Abonent</th><th>Login</th><th>Paket</th><th>IP</th><th>Status</th><th>Bitme</th><th>Son sync</th></tr></thead><tbody><?php foreach ($rows as $row): ?><tr data-billing-row><td><strong><a href="billing-customer-profile.php?id=<?= e((string) ($row['account_id'] ?? 0)); ?>"><?= e((string) ($row['subscriber_code'] ?? '-')); ?></a></strong><br><small><?= e((string) ($row['full_name'] ?? '-')); ?></small></td><td><?= e((string) ($row['username'] ?? '-')); ?></td><td><?= e((string) ($row['tariff_name'] ?? '-')); ?></td><td><?= e((string) ($row['assigned_ip'] ?? $row['static_ip'] ?? '-')); ?></td><td><?= e((string) ($row['status'] ?? '-')); ?></td><td><?= e((string) ($row['expires_at'] ?? '-')); ?></td><td><?= e((string) ($row['last_radius_sync_at'] ?? '-')); ?></td></tr><?php endforeach; ?><?php if ($rows === []): ?><tr><td colspan="7" class="billing-empty">Xidmet tapilmadi.</td></tr><?php endif; ?></tbody></table></div><?php require __DIR__ . '/_pagination.php'; ?></div>
